// Generated by nlayer: do not edit.
// `@nlayer/test` is what `nlayer test` serves. An app's bundle cannot import it.

export function test(name: string, fn: () => void): void;

export interface Expectation {
  toBe(expected: unknown): void;
  toEqual(expected: unknown): void;
  /** A string contains the text; an array contains an equal element. */
  toContain(part: unknown): void;
  toThrow(message?: string): void;
}

export function expect(actual: unknown): Expectation;

export interface Frame {
  x: number;
  y: number;
  width: number;
  height: number;
}

/** One view. `text` is a text view's content, `value` an input's, `src` an image's URL. */
export interface Node {
  kind: "view" | "text" | "image" | "scroll" | "input";
  frame: Frame;
  /** A view's `testID`, when it has one. */
  testID?: string;
  /** Its accessibility: what VoiceOver, TalkBack or ARIA reads. */
  role?: AccessibilityRole;
  accessibilityLabel?: string;
  accessibilityHint?: string;
  accessibilityHidden?: boolean;
  accessibilityState?: AccessibilityState;
  accessibilityValue?: AccessibilityValue;
  text?: string;
  /** Style runs of a text view, in order. `color` is `#rrggbb` or `#rrggbbaa`. */
  spans?: Array<{
    text: string;
    fontSize: number;
    fontWeight: number;
    italic: boolean;
    color: string;
  }>;
  value?: string;
  placeholder?: string;
  secure?: boolean;
  keyboard?: "text" | "email" | "number" | "phone";
  disabled?: boolean;
  /** The field is the one editing. `Keyboard.dismiss()` clears it. */
  focused?: boolean;
  src?: string;
  /** An image's `objectFit`. */
  fit?: "fill" | "contain" | "cover" | "none" | "scale-down";
  /** Painted corner radii in points, when the host clips the picture. */
  radius?: [number, number, number, number];
  /** A scroll view scrolls along x. */
  horizontal?: boolean;
  /** A scroll view's content offset, toward the end of the content. */
  offset?: { x: number; y: number };
  /** A scroll view's content size. */
  content?: { width: number; height: number };
  /** A view's static transform steps. Angles are degrees. */
  transform?: Array<Record<string, number>>;
  children: Node[];
}

export interface OpenOptions {
  /** Viewport in points. Defaults to 390×844. */
  width?: number;
  height?: number;
  safeArea?: { top: number; right: number; bottom: number; left: number };
  /** `env(keyboard-inset-height)`, in points. */
  keyboard?: number;
  /** The system color scheme before the first frame. Default: `light`. */
  colorScheme?: "light" | "dark";
  /**
   * The directory the headless app keeps its storage in, relative to the
   * test file. Default: in memory.
   */
  dataDir?: string;
}

/** The app `open` started, on a headless engine. */
export interface App {
  texts(): string[];
  inputs(): string[];
  /** Presses what `selector` names and waits for the frame. */
  press(selector: string): void;
  /** Types `text` into the input `selector` names, one change per character. */
  type(selector: string, text: string): void;
  /** Scrolls the scroll view `selector` names by `distance` points toward its content's end. */
  scroll(selector: string, distance: number): void;
  /** Waits until `selector` names one view that is on screen. */
  waitFor(selector: string): void;
  /** The mount tree from the surface root, with each view's frame. */
  tree(): Node;
  close(): void;
}

/** Starts `entry` (relative to the test file) and waits for its first frame. */
export function open(entry: string, options?: OpenOptions): App;

/** Runs the cases `test` registered. The entry `nlayer test` generates calls
 * this; a test file does not. */
export function finish(suite: unknown): void;
